fn solve(n: i8, s: Vec<char>) -> i8 {
    // Requires: n must be non-negative and less than or equal to the length of s
    // Ensures: The return value is the count of adjacent equal-character pairs in s
    // Decreases: n, as it is used in the loop condition
    // Invariant: At the start of each iteration, count is the number of adjacent equal-character pairs found in s[0..i]
    //            and i is the current index being checked.
    //            0 <= i < n - 1
    //            0 <= count <= (n - 1)
    //            s.len() == n as usize

    // Initialize a counter for adjacent equal-character pairs
    let mut count = 0;

    // Iterate through the array, checking adjacent characters
    for i in 0..(n - 1) {
        // Assert: i is within bounds
        assert!(0 <= i && i < n - 1);
        
        if s[i as usize] == s[(i + 1) as usize] {
            count += 1;
        }
        
        // Assert: After the check, count is updated correctly
        assert!(count >= 0);
    }

    // Ensures: The final count is returned
    count
}